import { useEffect, useState, type FormEvent, type MouseEventHandler, type ReactNode } from "react";
import { Activity, ArrowLeft, ArrowRight, BarChart3, Bell, Bot, BriefcaseBusiness, CheckCircle2, ChevronDown, Filter, Headphones, Inbox as InboxIcon, LayoutDashboard, Mail, Menu, MessageCircle, MoreHorizontal, Phone, Plus, Search, Send, Settings, ShieldCheck, Tag, UserRound, UsersRound, X } from "lucide-react";
import { api } from "./api";
import type { AppState, Channel, Contact, Conversation, Integration, Invite, Member, Message, Opportunity, Role, StageKey, User } from "./types";

type Page = "dashboard" | "inbox" | "crm" | "contacts" | "team" | "channels" | "settings";
type Toast = { tone: "success" | "error"; message: string };
type OpportunityCreate = { contactId: string; conversationId?: string };
const stageLabels: Record<StageKey, string> = { NEW_LEAD: "Novo lead", CONTACTED: "Contato realizado", PROPOSAL: "Proposta", NEGOTIATION: "Negociação", WON: "Ganho", LOST: "Perdido" };
const channelIcon: Record<string, ReactNode> = { WHATSAPP: <MessageCircle size={15} />, WEBCHAT: <Bot size={15} />, EMAIL: <Mail size={15} />, INSTAGRAM: <Activity size={15} /> };
const money = (value: number) => value.toLocaleString("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 });
const timeAgo = (date: string) => { const minutes = Math.max(1, Math.round((Date.now() - new Date(date).getTime()) / 60_000)); return minutes < 60 ? `${minutes} min` : `${Math.round(minutes / 60)}h`; };
const errorText = (error: unknown) => error instanceof Error ? error.message : "Não foi possível concluir a ação.";
async function loadState(): Promise<AppState> { const { user } = await api<{ user: User }>("/v1/auth/me"); const boot = await api<Omit<AppState, "user"> & { user: User }>("/v1/bootstrap"); return { ...boot, user }; }

function Login({ onLoggedIn }: { onLoggedIn: (state: AppState) => void }) {
  const [signup, setSignup] = useState(false); const [name, setName] = useState(""); const [organizationName, setOrganizationName] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); setLoading(true); setError(""); try { await api(signup ? "/v1/auth/signup" : "/v1/auth/login", { method: "POST", body: JSON.stringify(signup ? { name, email, password, organizationName } : { email, password }) }); onLoggedIn(await loadState()); } catch (err) { setError(errorText(err)); } finally { setLoading(false); } };
  return <main className="login-page"><div className="login-glow" /><section className="login-card"><div className="brand-mark"><span>e</span></div><div className="eyebrow">ATENDIMENTO OMNICHANNEL</div><h1>{signup ? <>Crie seu <em>workspace.</em></> : <>Converse. Conecte.<br /><em>Venda melhor.</em></>}</h1><p className="login-copy">{signup ? "Comece com um workspace isolado, equipe, pipeline e inbox prontos para o primeiro piloto." : "O workspace para transformar cada conversa em relacionamento e cada relacionamento em oportunidade."}</p><form onSubmit={submit}>{signup && <><label>Seu nome<input value={name} onChange={(event) => setName(event.target.value)} required minLength={2} autoComplete="name" /></label><label>Nome da empresa<input value={organizationName} onChange={(event) => setOrganizationName(event.target.value)} required minLength={2} autoComplete="organization" /></label></>}<label>Email profissional<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" required autoComplete="username" /></label><label>Senha<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" required minLength={8} autoComplete={signup ? "new-password" : "current-password"} /></label>{error && <div className="form-error">{error}</div>}<button className="primary-button wide" disabled={loading}>{loading ? "Aguarde…" : signup ? "Criar workspace" : "Entrar no eChat"}<ArrowRight size={17} /></button></form><button className="login-switch" onClick={() => { setSignup((value) => !value); setError(""); }}>{signup ? "Já tenho uma conta" : "Criar um novo workspace"}</button><div className="login-hint"><ShieldCheck size={15} /> Sessão segura · dados isolados por organização</div></section><div className="login-side"><div className="mini-preview"><div className="preview-top"><span className="preview-dot teal" /><span className="preview-dot" /><span className="preview-dot" /><span className="preview-title">Inbox</span><span className="preview-badge">MVP v1</span></div><div className="preview-body"><div className="preview-list"><div className="preview-line active" /><div className="preview-line" /><div className="preview-line" /><div className="preview-line" /></div><div className="preview-chat"><div className="preview-chat-head" /><div className="preview-bubble left" /><div className="preview-bubble right" /><div className="preview-bubble left short" /></div><div className="preview-context"><div className="preview-avatar">MS</div><strong>Maria Silva</strong><span>ACME Soluções</span><div className="preview-pill">Plano Pro</div></div></div></div><p>Uma visão única para operação, relacionamento e crescimento.</p></div></main>;
}

function InviteAccept({ token, onLoggedIn }: { token: string; onLoggedIn: (state: AppState) => void }) {
  const [info, setInfo] = useState<{ email: string; role: Role } | null>(null); const [name, setName] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  useEffect(() => { void api<{ email: string; role: Role }>(`/v1/invites/${encodeURIComponent(token)}`).then(setInfo).catch((err) => setError(errorText(err))); }, [token]);
  const submit = async (event: FormEvent) => { event.preventDefault(); setLoading(true); setError(""); try { await api(`/v1/invites/${encodeURIComponent(token)}`, { method: "POST", body: JSON.stringify({ name, password }) }); onLoggedIn(await loadState()); } catch (err) { setError(errorText(err)); } finally { setLoading(false); } };
  return <main className="login-page"><section className="login-card"><div className="brand-mark"><span>e</span></div><div className="eyebrow">CONVITE DE EQUIPE</div><h1>Entre no <em>eChat.</em></h1><p className="login-copy">{info ? `Convite para ${info.email} · perfil ${info.role}.` : "Validando seu convite…"}</p>{info && <form onSubmit={submit}><label>Seu nome<input value={name} onChange={(event) => setName(event.target.value)} required minLength={2} autoComplete="name" /></label><label>Senha<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" required minLength={8} autoComplete="new-password" /></label>{error && <div className="form-error">{error}</div>}<button className="primary-button wide" disabled={loading}>{loading ? "Entrando…" : "Aceitar convite"}<ArrowRight size={17} /></button></form>}{!info && error && <div className="form-error">{error}</div>}</section></main>;
}

function Button({ children, variant = "ghost", onClick, className = "", disabled = false, title, ariaLabel, type }: { children: ReactNode; variant?: "ghost" | "primary" | "soft" | "outline"; onClick?: MouseEventHandler<HTMLButtonElement>; className?: string; disabled?: boolean; title?: string; ariaLabel?: string; type?: "button" | "submit" }) { return <button type={type} disabled={disabled} title={title} aria-label={ariaLabel} onClick={onClick} className={`button ${variant} ${className}`}>{children}</button>; }
function Avatar({ user, size = "md" }: { user?: Pick<User, "name" | "avatar">; size?: "sm" | "md" | "lg" }) { return <span className={`avatar ${size}`}>{user?.avatar ?? user?.name.split(" ").map((part) => part[0]).join("").slice(0, 2) ?? "EC"}</span>; }
function Badge({ children, tone = "neutral" }: { children: ReactNode; tone?: "neutral" | "teal" | "green" | "amber" | "red" | "blue" }) { return <span className={`badge ${tone}`}>{children}</span>; }
function EmptyState({ title, body, action }: { title: string; body: string; action?: ReactNode }) { return <div className="empty-state"><strong>{title}</strong><span>{body}</span>{action}</div>; }
function Metric({ icon, label, value, detail, tone }: { icon: ReactNode; label: string; value: string; detail: string; tone: string }) { return <div className="metric-card"><div className={`metric-icon ${tone}`}>{icon}</div><div><p>{label}</p><strong>{value}</strong><small>{detail}</small></div></div>; }

function Sidebar({ page, setPage, user, organization, onLogout }: { page: Page; setPage: (page: Page) => void; user: User; organization: AppState["organization"]; onLogout: () => void }) {
  const items: { page: Page; label: string; icon: ReactNode }[] = [{ page: "dashboard", label: "Visão geral", icon: <LayoutDashboard size={18} /> }, { page: "inbox", label: "Inbox", icon: <InboxIcon size={18} /> }, { page: "crm", label: "CRM", icon: <BarChart3 size={18} /> }, { page: "contacts", label: "Contatos", icon: <UserRound size={18} /> }, { page: "team", label: "Equipe", icon: <UsersRound size={18} /> }, { page: "channels", label: "Canais", icon: <MessageCircle size={18} /> }, { page: "settings", label: "Configurações", icon: <Settings size={18} /> }];
  return <aside className="sidebar"><div className="sidebar-brand"><div className="brand-mark small"><span>e</span></div><div><strong>eChat</strong><small>CUSTOMER READY</small></div><Button disabled ariaLabel="Mais opções em breve" title="Mais opções em breve"><MoreHorizontal size={18} /></Button></div><div className="org-switch"><div className="org-icon">{organization.name.slice(0, 1).toUpperCase()}</div><div><strong>{organization.name}</strong><small>{organization.plan}</small></div><ChevronDown size={15} /></div><p className="sidebar-label">MENU PRINCIPAL</p><nav>{items.map((item) => <button key={item.page} className={`nav-item ${page === item.page ? "active" : ""}`} onClick={() => setPage(item.page)}>{item.icon}<span>{item.label}</span></button>)}</nav><div className="sidebar-bottom"><div className="presence"><span /> Online agora</div><div className="profile-row"><Avatar user={user} /><div><strong>{user.name}</strong><small>{user.role === "OWNER" ? "Owner / Operação" : user.role}</small></div><MoreHorizontal size={17} /></div><button className="logout-button" onClick={onLogout}>Encerrar sessão</button></div></aside>;
}
function Topbar({ page, onMenu }: { page: Page; onMenu: () => void }) { const labels: Record<Page, string> = { dashboard: "Visão geral", inbox: "Inbox", crm: "CRM", contacts: "Contatos", team: "Equipe", channels: "Canais", settings: "Configurações" }; return <header className="topbar"><button className="mobile-menu" onClick={onMenu} aria-label="Abrir menu"><Menu size={20} /></button><div className="breadcrumbs"><span>Workspace</span><ChevronDown size={14} /><strong>{labels[page]}</strong><span className="health"><i /> Operação estável</span></div><div className="topbar-actions"><div className="global-search"><Search size={16} /><span>Buscar no workspace</span><kbd>Ctrl K</kbd></div><button className="icon-button" disabled aria-label="Notificações em breve" title="Notificações em breve"><Bell size={18} /><i /></button></div></header>; }

function Dashboard({ state, setPage }: { state: AppState; setPage: (page: Page) => void }) { const open = state.conversations.filter((item) => item.status !== "RESOLVED").length; const unassigned = state.conversations.filter((item) => !item.assignedToId).length; const total = state.opportunities.filter((item) => !["WON", "LOST"].includes(item.stage)).reduce((sum, item) => sum + item.value, 0); return <div className="page dashboard-page"><div className="page-heading"><div><div className="eyebrow">OPERAÇÃO CUSTOMER-READY</div><h1>Bom dia, {state.user.name.split(" ")[0]} <span>✦</span></h1><p>Veja o que está acontecendo na sua operação hoje.</p></div><div className="heading-actions"><Button variant="outline" onClick={() => setPage("settings")}><Settings size={16} /> Configurar</Button><Button variant="outline" onClick={() => setPage("channels")}><MessageCircle size={16} /> Canais</Button></div></div><div className="metrics-grid"><Metric tone="teal" icon={<MessageCircle size={18} />} label="Conversas abertas" value={String(open)} detail="Dados persistidos" /><Metric tone="amber" icon={<Headphones size={18} />} label="Não atribuídas" value={String(unassigned)} detail="Atenção necessária" /><Metric tone="blue" icon={<UserRound size={18} />} label="Contatos" value={String(state.contacts.length)} detail="Tenant isolado" /><Metric tone="green" icon={<BriefcaseBusiness size={18} />} label="Em negociação" value={money(total)} detail="Pipeline ativo" /></div><div className="dashboard-grid"><section className="panel attention-panel"><div className="panel-heading"><div><h2>Conversas que precisam de atenção</h2><p>Fila operacional persistida no banco</p></div><Button variant="soft" onClick={() => setPage("inbox")}>Ver inbox <ArrowRight size={15} /></Button></div><div className="attention-list">{state.conversations.slice(0, 5).map((conversation) => { const contact = state.contacts.find((item) => item.id === conversation.contactId); const owner = state.users.find((item) => item.id === conversation.assignedToId); return <div className="attention-row" key={conversation.id}><Avatar user={owner ?? { name: contact?.name ?? "Contato", avatar: "CT" }} /><div className="attention-main"><strong>{contact?.name ?? "Contato"}</strong><span>{conversation.lastMessage || "Sem mensagem"}</span><small>{channelIcon[state.channels.find((channel) => channel.id === conversation.channelId)?.type ?? "WEBCHAT"]} {owner?.name ?? "Sem atendente"} · há {timeAgo(conversation.lastMessageAt)}</small></div><Badge tone={conversation.status === "WAITING" ? "amber" : conversation.assignedToId ? "neutral" : "red"}>{conversation.status === "WAITING" ? "Aguardando" : conversation.assignedToId ? "Atribuída" : "Atenção"}</Badge><Button variant="outline" onClick={() => setPage("inbox")}>Atender</Button></div>; })}</div>{state.conversations.length === 0 && <EmptyState title="Nenhuma conversa ainda" body="Conecte um canal ou rode uma sincronização para importar conversas." />}</section><section className="panel pipeline-summary"><div className="panel-heading"><div><h2>Pipeline de vendas</h2><p>Total em aberto · {money(total)}</p></div><Button variant="soft" onClick={() => setPage("crm")}>Abrir CRM <ArrowRight size={15} /></Button></div><div className="summary-bars">{state.stages.slice(0, 4).map((stage) => { const opportunities = state.opportunities.filter((item) => item.stage === stage.key); const value = opportunities.reduce((sum, item) => sum + item.value, 0); return <div className="summary-bar" key={stage.id}><div><span><i className={`stage-dot ${stage.color}`} />{stage.name}</span><strong>{money(value)}</strong></div><div className="progress"><i style={{ width: `${Math.min(100, Math.max(8, opportunities.length * 20))}%` }} /></div><small>{opportunities.length} oportunidades</small></div>; })}</div></section></div></div>; }

function Inbox({ state, setState, onOpenContact, onOpenOpportunity, onCreateOpportunity, notify }: { state: AppState; setState: (state: AppState) => void; onOpenContact: (contact: Contact) => void; onOpenOpportunity: (opportunity: Opportunity) => void; onCreateOpportunity: (contact: Contact, conversationId?: string) => void; notify: (toast: Toast) => void }) {
  const [selectedId, setSelectedId] = useState(state.conversations[0]?.id); const [query, setQuery] = useState(""); const [filter, setFilter] = useState<"all" | "mine" | "unassigned" | "WAITING" | "RESOLVED">("all"); const [draft, setDraft] = useState(""); const [internal, setInternal] = useState(false); const [mobileView, setMobileView] = useState<"list" | "chat" | "context">("list"); const [error, setError] = useState(""); const [loading, setLoading] = useState(false); const [sending, setSending] = useState(false);
  const selected = state.conversations.find((item) => item.id === selectedId) ?? state.conversations[0]; const contact = state.contacts.find((item) => item.id === selected?.contactId); const channel = state.channels.find((item) => item.id === selected?.channelId); const owner = state.users.find((item) => item.id === selected?.assignedToId);
  const refresh = async () => { setLoading(true); setError(""); try { const params = new URLSearchParams(); if (query.trim()) params.set("query", query.trim()); if (filter === "mine" || filter === "unassigned") params.set("assignedToId", filter); if (filter === "WAITING" || filter === "RESOLVED") params.set("status", filter); const result = await api<{ conversations: Conversation[] }>(`/v1/conversations${params.size ? `?${params}` : ""}`); setState({ ...state, conversations: result.conversations }); if (result.conversations.length && !result.conversations.some((item) => item.id === selectedId)) setSelectedId(result.conversations[0].id); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } finally { setLoading(false); } };
  useEffect(() => { const timer = window.setTimeout(() => void refresh(), 250); return () => window.clearTimeout(timer); }, [query, filter]);
  const replaceConversation = (conversation: Conversation) => setState({ ...state, conversations: state.conversations.map((item) => item.id === conversation.id ? conversation : item) });
  const send = async () => { if (!draft.trim() || !selected || sending) return; setSending(true); setError(""); try { const result = await api<{ message: Message }>(`/v1/conversations/${selected.id}/messages`, { method: "POST", body: JSON.stringify({ body: draft.trim(), internal }) }); replaceConversation({ ...selected, lastMessage: result.message.body, lastMessageAt: result.message.createdAt, messages: [...selected.messages, result.message] }); setDraft(""); notify({ tone: "success", message: internal ? "Nota interna adicionada." : "Mensagem enviada." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } finally { setSending(false); } };
  const assign = async () => { if (!selected) return; try { const result = await api<{ conversation: Conversation }>(`/v1/conversations/${selected.id}/assign`, { method: "PATCH", body: JSON.stringify({ assignedToId: selected.assignedToId ? null : state.user.id }) }); replaceConversation(result.conversation); notify({ tone: "success", message: result.conversation.assignedToId ? "Conversa atribuída." : "Conversa desatribuída." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } };
  const changeStatus = async () => { if (!selected) return; const action = selected.status === "RESOLVED" ? "reopen" : "resolve"; try { const result = await api<{ conversation: Conversation }>(`/v1/conversations/${selected.id}/${action}`, { method: "POST" }); replaceConversation(result.conversation); notify({ tone: "success", message: result.conversation.status === "RESOLVED" ? "Conversa resolvida." : "Conversa reaberta." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } };
  const rootClass = `inbox-page ${mobileView === "list" ? "show-list" : ""} ${mobileView === "context" ? "show-context" : ""}`;
  return <div className={rootClass}><section className="inbox-list"><div className="inbox-list-head"><div><div className="eyebrow">ATENDIMENTO</div><h1>Inbox <Badge tone="teal">{state.conversations.length}</Badge></h1></div><Button variant="primary" onClick={() => void refresh()}><Plus size={16} /> Atualizar</Button></div><div className="inbox-tabs">{([["all", "Todas"], ["mine", "Minhas"], ["unassigned", "Não atribuídas"], ["WAITING", "Aguardando"], ["RESOLVED", "Resolvidas"]] as const).map(([value, label]) => <button key={value} className={filter === value ? "active" : ""} onClick={() => setFilter(value)}>{label}</button>)}</div><div className="list-search"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar conversas" /></div>{loading && <div className="list-loading">Carregando fila…</div>}<div className="conversation-items">{state.conversations.map((item) => { const itemContact = state.contacts.find((candidate) => candidate.id === item.contactId); const itemChannel = state.channels.find((candidate) => candidate.id === item.channelId); const itemOwner = state.users.find((candidate) => candidate.id === item.assignedToId); if (!itemContact) return null; return <button className={`conversation-item ${selected?.id === item.id ? "selected" : ""}`} onClick={() => { setSelectedId(item.id); setMobileView("chat"); }} key={item.id}><Avatar user={{ name: itemContact.name, avatar: itemContact.name.split(" ").map((part) => part[0]).join("").slice(0, 2) }} /><span className="conversation-copy"><strong>{itemContact.name}</strong><small>{timeAgo(item.lastMessageAt)} · {item.lastMessage || "Sem mensagem"}</small><em>{channelIcon[itemChannel?.type ?? "WEBCHAT"]} {itemOwner?.name ?? "Não atribuído"}</em></span>{item.unread > 0 && <b className="unread">{item.unread}</b>}</button>; })}</div>{!loading && state.conversations.length === 0 && <EmptyState title="Fila vazia" body="Não há conversas para este filtro." />}</section><section className="chat-panel">{error && <div className="form-error">{error}</div>}{selected ? <><div className="chat-header"><div className="chat-header-left"><button className="mobile-back" onClick={() => setMobileView("list")} aria-label="Voltar para a lista"><ArrowLeft size={17} /></button><div className="chat-person"><Avatar size="lg" user={{ name: contact?.name ?? "Contato", avatar: contact?.name.split(" ").map((part) => part[0]).join("").slice(0, 2) ?? "CT" }} /><div><h2>{contact?.name ?? "Contato"}</h2><p><span className="online-dot" /> {selected.status} · {channel?.name ?? "Canal"} · {contact?.phone}</p></div></div></div><div className="chat-header-actions"><Button variant="soft" onClick={() => void assign()}><UserRound size={16} /> {owner ? "Desatribuir" : "Atribuir"}</Button><Button variant="outline" onClick={() => void changeStatus()}><CheckCircle2 size={16} /> {selected.status === "RESOLVED" ? "Reabrir" : "Resolver"}</Button></div></div><div className="chat-messages"><div className="date-divider">Histórico</div>{selected.messages.map((message) => <div className={`message-row ${message.sender === "AGENT" ? "agent" : message.internal ? "internal" : ""}`} key={message.id}>{message.sender !== "AGENT" && <Avatar size="sm" user={{ name: message.authorName, avatar: message.authorName.split(" ").map((part) => part[0]).join("").slice(0, 2) }} />}<div className="message-wrap"><span>{message.authorName} · {new Date(message.createdAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</span><div className="message-bubble">{message.internal && <small><ShieldCheck size={13} /> Nota interna</small>}{message.body}</div></div></div>)}</div><div className="composer"><div className="composer-tabs"><button className={!internal ? "active" : ""} onClick={() => setInternal(false)}>Resposta pública</button><button className={internal ? "active internal-tab" : ""} onClick={() => setInternal(true)}><ShieldCheck size={14} /> Nota interna</button></div><textarea value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={internal ? "Escreva uma nota para a equipe…" : "Escreva uma resposta…"} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); void send(); } }} /><div className="composer-actions"><span>/ respostas para macros</span><div><Button disabled ariaLabel="Atalhos em breve" title="Atalhos em breve"><Tag size={16} /></Button><Button variant="primary" disabled={sending} onClick={() => void send()}>{sending ? "Enviando…" : <><Send size={15} /> Enviar</>}</Button></div></div></div></> : <EmptyState title="Nenhuma conversa selecionada" body="Selecione uma conversa para começar." />}</section><aside className="contact-context"><div className="context-head"><h2>Detalhes do contato</h2><button onClick={() => setMobileView("chat")}><X size={18} /></button></div>{contact ? <><div className="context-profile"><Avatar size="lg" user={{ name: contact.name, avatar: contact.name.split(" ").map((part) => part[0]).join("").slice(0, 2) }} /><h2>{contact.name}</h2><p>{contact.company}</p><div className="quick-actions"><Button variant="soft" disabled title="Ação em breve"><Phone size={15} /> Ligar</Button><Button variant="soft" disabled title="Ação em breve"><Mail size={15} /> Email</Button></div></div><div className="context-section"><div className="context-label">DADOS PRINCIPAIS</div><dl><dt>Telefone</dt><dd>{contact.phone || "—"}</dd><dt>Email</dt><dd>{contact.email || "—"}</dd><dt>Responsável</dt><dd>{owner?.name ?? "Não atribuído"}</dd></dl></div><div className="context-section"><div className="context-label">TAGS</div><div className="tag-list">{contact.tags.map((tag) => <Badge tone={tag.includes("Plano") ? "teal" : "neutral"} key={tag}>{tag}</Badge>)}</div></div><Button variant="primary" onClick={() => contact && onCreateOpportunity(contact, selected?.id)}><BriefcaseBusiness size={15} /> Criar oportunidade</Button>{state.opportunities.filter((item) => item.contactId === contact.id).map((opportunity) => <button className="context-opportunity" key={opportunity.id} onClick={() => onOpenOpportunity(opportunity)}><div><span><BriefcaseBusiness size={14} /> Oportunidade CRM</span><strong>{opportunity.title}</strong><small>{money(opportunity.value)} · {stageLabels[opportunity.stage]}</small></div><ArrowRight size={16} /></button>)}<div className="context-section note"><div className="context-label">NOTAS RÁPIDAS</div><p>“{contact.notes || "Sem notas"}”</p></div><button className="mobile-contact-button" onClick={() => onOpenContact(contact)}>Abrir contato completo <ArrowRight size={15} /></button></> : <EmptyState title="Contato indisponível" body="A conversa ainda não tem contato associado." />}</aside><button className="mobile-context-toggle" onClick={() => setMobileView("context")}>Contato <ArrowRight size={15} /></button></div>;
}

function Crm({ state, setState, onOpenOpportunity, onCreateOpportunity, notify }: { state: AppState; setState: (state: AppState) => void; onOpenOpportunity: (opportunity: Opportunity) => void; onCreateOpportunity: (contact: Contact) => void; notify: (toast: Toast) => void }) { const [search, setSearch] = useState(""); const [error, setError] = useState(""); const create = () => { const contact = state.contacts[0]; if (contact) onCreateOpportunity(contact); else notify({ tone: "error", message: "Adicione um contato antes de criar uma oportunidade." }); }; const move = async (opportunity: Opportunity, direction: number) => { const active = state.stages.filter((stage) => stage.key !== "LOST"); const index = active.findIndex((stage) => stage.key === opportunity.stage); const nextStage = active[index + direction]; if (!nextStage) return; try { const result = await api<{ opportunity: Opportunity }>(`/v1/opportunities/${opportunity.id}/move`, { method: "PATCH", body: JSON.stringify({ stage: nextStage.key }) }); setState({ ...state, opportunities: state.opportunities.map((item) => item.id === opportunity.id ? result.opportunity : item) }); notify({ tone: "success", message: "Oportunidade movida." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } }; const stages = state.stages.filter((stage) => stage.key !== "LOST"); return <div className="page crm-page">{error && <div className="form-error">{error}</div>}<div className="page-heading"><div><div className="eyebrow">COMERCIAL · PIPELINE</div><h1>Pipeline de vendas</h1><p>Conversa, contato e oportunidade em uma mesma operação.</p></div><Button variant="primary" onClick={create}><Plus size={16} /> Nova oportunidade</Button></div><div className="crm-summary"><div><span>Oportunidades ativas</span><strong>{state.opportunities.filter((item) => !["WON", "LOST"].includes(item.stage)).length}</strong></div><div><span>Total em pipeline</span><strong>{money(state.opportunities.filter((item) => !["WON", "LOST"].includes(item.stage)).reduce((sum, item) => sum + item.value, 0))}</strong></div><div><span>Taxa de conversão</span><strong>—</strong></div><div className="crm-filter"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar oportunidade" /><Filter size={16} /></div></div><div className="kanban-board">{stages.map((stage) => { const opportunities = state.opportunities.filter((item) => item.stage === stage.key && (!search || item.title.toLowerCase().includes(search.toLowerCase()) || item.company.toLowerCase().includes(search.toLowerCase()))); return <section className="kanban-column" key={stage.key}><div className="kanban-head"><div><span><i className={`stage-dot ${stage.color}`} />{stage.name}</span><b>{opportunities.length}</b></div><small>{money(opportunities.reduce((sum, item) => sum + item.value, 0))}</small></div><div className="kanban-cards">{opportunities.map((opportunity) => { const owner = state.users.find((user) => user.id === opportunity.ownerId); const contact = state.contacts.find((item) => item.id === opportunity.contactId); return <article className="opportunity-card" key={opportunity.id} onClick={() => onOpenOpportunity(opportunity)}><div className="opportunity-title"><strong>{opportunity.title}</strong><MoreHorizontal size={16} /></div><span className="opportunity-company">{opportunity.company}</span><div className="opportunity-value">{money(opportunity.value)}<Badge tone="neutral">{opportunity.source}</Badge></div><div className="opportunity-meta"><Avatar size="sm" user={owner} /><span>{owner?.name.split(" ")[0]}</span><span>·</span><span>{opportunity.lastActivity}</span></div><div className="opportunity-contact"><UserRound size={13} /> {contact?.name}</div><div className="card-actions"><Button ariaLabel={"Mover " + opportunity.title + " para a etapa anterior"} title="Mover para a etapa anterior" onClick={(event) => { event.stopPropagation(); void move(opportunity, -1); }}><ArrowLeft size={13} /></Button><Button ariaLabel={"Mover " + opportunity.title + " para a próxima etapa"} title="Mover para a próxima etapa" onClick={(event) => { event.stopPropagation(); void move(opportunity, 1); }}><ArrowRight size={13} /></Button></div></article>; })}<button className="add-card" onClick={create}><Plus size={16} /> Adicionar oportunidade</button></div></section>; })}</div></div>; }

function Contacts({ state, setState, onOpenContact }: { state: AppState; setState: (state: AppState) => void; onOpenContact: (contact: Contact) => void }) { const [query, setQuery] = useState(""); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); useEffect(() => { const timer = window.setTimeout(() => { setLoading(true); void api<{ contacts: Contact[] }>(`/v1/contacts?query=${encodeURIComponent(query)}`).then((result) => setState({ ...state, contacts: result.contacts })).catch((err) => setError(errorText(err))).finally(() => setLoading(false)); }, 250); return () => window.clearTimeout(timer); }, [query]); return <div className="page contacts-page">{error && <div className="form-error">{error}</div>}<div className="page-heading"><div><div className="eyebrow">RELACIONAMENTO</div><h1>Contatos</h1><p>Uma visão viva de pessoas, empresas e oportunidades.</p></div><Button variant="primary" onClick={() => setQuery("")}><Plus size={16} /> Limpar busca</Button></div><div className="table-toolbar"><div className="table-search"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por nome, empresa ou email" /></div><Button variant="outline" disabled>{loading ? "Buscando…" : `${state.contacts.length} contatos`}</Button></div><section className="panel contact-table"><div className="contact-table-head"><span>CONTATO</span><span>EMPRESA</span><span>TELEFONE</span><span>TAGS</span><span>RESPONSÁVEL</span><span>OPORTUNIDADES</span><span /></div>{state.contacts.map((contact) => { const owner = state.users.find((user) => user.id === contact.ownerId); return <button className="contact-table-row" key={contact.id} onClick={() => onOpenContact(contact)}><span className="contact-name"><Avatar user={{ name: contact.name, avatar: contact.name.split(" ").map((part) => part[0]).join("").slice(0, 2) }} /><strong>{contact.name}</strong><small>{contact.email}</small></span><span>{contact.company}</span><span>{contact.phone}</span><span className="table-tags">{contact.tags.slice(0, 2).map((tag) => <Badge key={tag}>{tag}</Badge>)}</span><span className="owner-cell"><Avatar size="sm" user={owner} />{owner?.name.split(" ")[0] ?? "—"}</span><span><b className="opportunity-count">{contact.opportunities}</b></span><ArrowRight size={17} /></button>; })}</section>{!loading && state.contacts.length === 0 && <EmptyState title="Nenhum contato encontrado" body="A busca não retornou contatos neste workspace." />}</div>; }

function TeamPage({ state, setState, notify }: { state: AppState; setState: (state: AppState) => void; notify: (toast: Toast) => void }) {
  const [email, setEmail] = useState(""); const [role, setRole] = useState<Role>("AGENT"); const [inviteUrl, setInviteUrl] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  const invite = async (event: FormEvent) => { event.preventDefault(); setLoading(true); setError(""); try { const result = await api<{ invite: Invite; inviteUrl: string }>("/v1/members/invites", { method: "POST", body: JSON.stringify({ email, role }) }); setState({ ...state, invites: [result.invite, ...state.invites] }); setInviteUrl(result.inviteUrl); setEmail(""); notify({ tone: "success", message: "Convite criado. Copie o link para enviar ao membro." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } finally { setLoading(false); } };
  const copyInvite = async () => { if (!inviteUrl) return; try { await navigator.clipboard?.writeText(inviteUrl); notify({ tone: "success", message: "Link do convite copiado." }); } catch (err) { notify({ tone: "error", message: errorText(err) }); } };
  const update = async (member: Member, input: { role?: Role; status?: "ACTIVE" | "DISABLED" }) => { try { const result = await api<{ member: Member }>("/v1/members/" + member.userId, { method: "PATCH", body: JSON.stringify(input) }); setState({ ...state, members: state.members.map((item) => item.userId === member.userId ? result.member : item), users: state.users.map((item) => item.id === member.userId ? { ...item, role: result.member.role } : item) }); notify({ tone: "success", message: "Membro atualizado." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } };
  return <div className="page"><div className="page-heading"><div><div className="eyebrow">OPERAÇÃO</div><h1>Equipe</h1><p>Convide e gerencie pessoas com roles e status auditáveis.</p></div></div>{error && <div className="form-error">{error}</div>}<section className="panel form-panel"><form className="inline-form" onSubmit={invite}><label>Email do membro<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" required placeholder="pessoa@empresa.com" /></label><label>Perfil<select value={role} onChange={(event) => setRole(event.target.value as Role)}><option value="AGENT">Agent</option><option value="ADMIN">Admin</option></select></label><Button variant="primary" disabled={loading}><Plus size={16} /> {loading ? "Gerando…" : "Gerar convite"}</Button></form>{inviteUrl && <div className="invite-result"><strong>Convite criado</strong><span>{inviteUrl}</span><Button variant="soft" onClick={() => void copyInvite()}>Copiar link</Button></div>}</section><section className="panel team-grid">{state.members.map((member) => <div className="team-card" key={member.userId}><Avatar size="lg" user={member} /><div><strong>{member.name}</strong><span>{member.email}</span><Badge tone={member.role === "OWNER" ? "teal" : member.status === "DISABLED" ? "red" : "neutral"}>{member.role} · {member.status}</Badge></div>{state.user.role !== "AGENT" && <div className="team-actions"><select value={member.role} onChange={(event) => void update(member, { role: event.target.value as Role })} disabled={member.role === "OWNER"}><option value="OWNER">Owner</option><option value="ADMIN">Admin</option><option value="AGENT">Agent</option></select><Button disabled={member.role === "OWNER"} title={member.role === "OWNER" ? "O proprietário não pode ser desativado por este fluxo." : undefined} onClick={() => void update(member, { status: member.status === "ACTIVE" ? "DISABLED" : "ACTIVE" })}>{member.status === "ACTIVE" ? "Desativar" : "Ativar"}</Button></div>}</div>)}</section><section className="panel invite-list"><div className="panel-heading"><div><h2>Convites pendentes</h2><p>O token bruto é exibido somente no momento da criação.</p></div></div>{state.invites.filter((invite) => !invite.acceptedAt && !invite.revokedAt).map((invite) => <div className="activity-row" key={invite.id}><span>{invite.email}</span><span>{invite.role}</span><span>Expira {new Date(invite.expiresAt).toLocaleDateString("pt-BR")}</span><span>Pendente</span><span>—</span></div>)}</section></div>;
}

function ChannelsPage({ state, setState, notify }: { state: AppState; setState: (state: AppState) => void; notify: (toast: Toast) => void }) {
  const [form, setForm] = useState({ displayName: "Chatwoot", baseUrl: "https://chatwoot.example.com", externalAccountId: "", apiToken: "", webhookSecret: "" }); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  const save = async (event: FormEvent) => { event.preventDefault(); setLoading(true); setError(""); try { const result = await api<{ integration: Integration }>("/v1/integrations", { method: "POST", body: JSON.stringify({ provider: "chatwoot", ...form }) }); setState({ ...state, integrations: [result.integration, ...state.integrations] }); setForm({ ...form, apiToken: "", webhookSecret: "" }); notify({ tone: "success", message: "Conexão salva com segurança." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } finally { setLoading(false); } };
  const test = async (integration: Integration) => { try { const result = await api<{ integration: Integration }>("/v1/integrations/" + integration.id + "/test", { method: "POST" }); setState({ ...state, integrations: state.integrations.map((item) => item.id === integration.id ? result.integration : item) }); notify({ tone: "success", message: "Teste de conexão concluído." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } };
  const sync = async (integration: Integration) => { try { const result = await api<{ integration: Integration }>("/v1/integrations/" + integration.id + "/sync", { method: "POST" }); setState({ ...state, integrations: state.integrations.map((item) => item.id === integration.id ? result.integration : item) }); notify({ tone: "success", message: "Sincronização concluída." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } };
  const frozenTypes = new Set(["WHATSAPP", "INSTAGRAM"]);
  return <div className="page"><div className="page-heading"><div><div className="eyebrow">OMNICHANNEL</div><h1>Canais</h1><p>Mock local ativo; conectividade externa permanece congelada neste ciclo.</p></div></div>{error && <div className="form-error">{error}</div>}<section className="panel form-panel"><div className="panel-heading"><div><h2>Conectar Chatwoot</h2><p>O token e o segredo são cifrados antes de persistir e nunca retornam à interface.</p></div></div><form className="integration-form" onSubmit={save}><label>Nome exibido<input value={form.displayName} onChange={(event) => setForm({ ...form, displayName: event.target.value })} required /></label><label>Base URL<input value={form.baseUrl} onChange={(event) => setForm({ ...form, baseUrl: event.target.value })} type="url" required /></label><label>Account ID<input value={form.externalAccountId} onChange={(event) => setForm({ ...form, externalAccountId: event.target.value })} required /></label><label>API token<input value={form.apiToken} onChange={(event) => setForm({ ...form, apiToken: event.target.value })} type="password" placeholder="Nunca exibido após salvar" required /></label><label>Webhook secret<input value={form.webhookSecret} onChange={(event) => setForm({ ...form, webhookSecret: event.target.value })} type="password" placeholder="Opcional" /></label><Button variant="primary" disabled={loading}><Plus size={16} /> {loading ? "Salvando…" : "Salvar conexão"}</Button></form></section><div className="channel-grid">{state.integrations.map((integration) => <section className="panel channel-card" key={integration.id}><div className="channel-icon">{integration.provider === "chatwoot" ? <MessageCircle size={18} /> : <Bot size={18} />}</div><div><strong>{integration.displayName}</strong><span>{integration.provider === "mock" ? "Mock local" : "Chatwoot · conta " + integration.externalAccountId}</span><small>{integration.lastSyncStatus ? "Sync: " + integration.lastSyncStatus : "Ainda não sincronizado"}</small></div><Badge tone={integration.status === "CONNECTED" ? "green" : integration.status === "ERROR" ? "red" : "amber"}>{integration.status}</Badge><div className="card-actions"><Button variant="soft" onClick={() => void test(integration)}>Testar</Button><Button variant="outline" onClick={() => void sync(integration)}>Sincronizar</Button></div></section>)}</div><section className="channel-grid">{state.channels.map((channel: Channel) => { const frozen = frozenTypes.has(channel.type); return <div className={"panel channel-card " + (frozen ? "channel-card-disabled" : "")} key={channel.id}><div className="channel-icon">{channelIcon[channel.type]}</div><div><strong>{channel.name}</strong><span>{frozen ? "Conectividade congelada neste ciclo" : channel.conversations + " conversas ativas · mock local"}</span></div><Badge tone={frozen ? "amber" : channel.status === "CONNECTED" ? "green" : "amber"}>{frozen ? "EM BREVE" : "MOCK LOCAL"}</Badge></div>; })}</section></div>;
}

function SettingsPage({ state, setState, notify }: { state: AppState; setState: (state: AppState) => void; notify: (toast: Toast) => void }) {
  const [name, setName] = useState(state.organization.name); const [timezone, setTimezone] = useState(state.organization.timezone); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  const save = async (event: FormEvent) => { event.preventDefault(); setLoading(true); setError(""); try { const result = await api<{ organization: AppState["organization"] }>("/v1/organization", { method: "PATCH", body: JSON.stringify({ name, timezone }) }); setState({ ...state, organization: result.organization }); notify({ tone: "success", message: "Preferências salvas." }); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } finally { setLoading(false); } };
  return <div className="page"><div className="page-heading"><div><div className="eyebrow">WORKSPACE</div><h1>Configurações</h1><p>Preferências da organização, timezone e estado do onboarding.</p></div></div>{error && <div className="form-error">{error}</div>}<section className="panel form-panel"><form className="settings-form" onSubmit={save}><label>Nome da organização<input value={name} onChange={(event) => setName(event.target.value)} /></label><label>Fuso horário<input value={timezone} onChange={(event) => setTimezone(event.target.value)} placeholder="America/Sao_Paulo" /></label><Button variant="primary" disabled={loading}>{loading ? "Salvando…" : "Salvar preferências"}</Button></form></section><section className="panel settings-list"><div><div className="settings-icon"><ShieldCheck size={18} /></div><div><strong>Segurança e acesso</strong><span>Roles, convites, sessão HttpOnly e isolamento por organização</span></div><Badge tone="teal">ATIVO</Badge></div><div><div className="settings-icon"><Bot size={18} /></div><div><strong>Provedores de mensagens</strong><span>{state.integrations.length ? String(state.integrations.length) + " integração(ões) configurada(s)" : "Mock Provider pronto · Chatwoot não conectado"}</span></div><Badge tone={state.integrations.length ? "green" : "teal"}>{state.integrations.length ? "CONFIGURADO" : "MOCK ATIVO"}</Badge></div></section></div>;
}

function Onboarding({ state, setState }: { state: AppState; setState: (state: AppState) => void }) { const steps: { key: AppState["organization"]["onboardingStep"]; label: string }[] = [{ key: "COMPANY", label: "Empresa" }, { key: "TEAM", label: "Equipe" }, { key: "CHANNEL", label: "Canal" }, { key: "DONE", label: "Pronto" }]; const complete = async (step: AppState["organization"]["onboardingStep"], done = false) => { try { const result = await api<{ organization: AppState["organization"] }>("/v1/organization", { method: "PATCH", body: JSON.stringify({ onboardingStep: step, onboardingCompleted: done }) }); setState({ ...state, organization: result.organization }); } catch { /* onboarding não bloqueia o workspace */ } }; return !state.organization.onboardingCompleted ? <section className="onboarding-card"><div><div className="eyebrow">PRIMEIRO SETUP</div><h2>Prepare seu workspace para o piloto</h2><p>Complete o básico agora e continue operando enquanto configura integrações.</p></div><div className="onboarding-steps">{steps.map((step, index) => <button key={step.key} className={state.organization.onboardingStep === step.key ? "active" : ""} onClick={() => void complete(step.key, step.key === "DONE")}><b>{index + 1}</b>{step.label}</button>)}</div><Button variant="soft" onClick={() => void complete("DONE", true)}>Concluir depois</Button></section> : null; }

function OpportunityFormModal({ state, initialContactId, initialConversationId, onClose, onCreated, notify }: { state: AppState; initialContactId: string; initialConversationId?: string; onClose: () => void; onCreated: (opportunity: Opportunity) => void; notify: (toast: Toast) => void }) {
  const [title, setTitle] = useState(""); const [contactId, setContactId] = useState(initialContactId); const [value, setValue] = useState("1200"); const [stage, setStage] = useState<StageKey>("NEW_LEAD"); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); }; window.addEventListener("keydown", onKeyDown); return () => window.removeEventListener("keydown", onKeyDown); }, [onClose]);
  const submit = async (event: FormEvent) => { event.preventDefault(); const numericValue = Number(value.replace(",", ".")); if (!title.trim() || !contactId || !Number.isFinite(numericValue) || numericValue < 0) { setError("Preencha título, contato e um valor válido."); return; } setLoading(true); setError(""); try { const result = await api<{ opportunity: Opportunity }>("/v1/opportunities", { method: "POST", body: JSON.stringify({ title: title.trim(), contactId, value: numericValue, stage, conversationId: initialConversationId }) }); onCreated(result.opportunity); } catch (err) { setError(errorText(err)); notify({ tone: "error", message: errorText(err) }); } finally { setLoading(false); } };
  return <div className="modal-backdrop" onClick={onClose}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="opportunity-modal-title" onClick={(event) => event.stopPropagation()}><div className="modal-heading"><div><div className="eyebrow">CRM</div><h2 id="opportunity-modal-title">Criar oportunidade</h2><p>Registre uma oportunidade sem sair do contexto atual.</p></div><button type="button" className="modal-close" onClick={onClose} aria-label="Fechar criação de oportunidade"><X size={18} /></button></div><form className="opportunity-form" onSubmit={submit}><label>Título<input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Ex.: Plano Pro — Maria Silva" required /></label><label>Contato<select value={contactId} onChange={(event) => setContactId(event.target.value)}>{state.contacts.map((contact) => <option key={contact.id} value={contact.id}>{contact.name} · {contact.company}</option>)}</select></label><label>Valor<input value={value} onChange={(event) => setValue(event.target.value)} type="number" min="0" step="0.01" required /></label><label>Etapa<select value={stage} onChange={(event) => setStage(event.target.value as StageKey)}>{state.stages.filter((item) => !["WON", "LOST"].includes(item.key)).map((item) => <option key={item.key} value={item.key}>{item.name}</option>)}</select></label>{error && <div className="form-error">{error}</div>}<div className="modal-actions"><Button variant="outline" type="button" onClick={onClose}>Cancelar</Button><Button variant="primary" disabled={loading}>{loading ? "Salvando…" : "Criar oportunidade"}</Button></div></form></section></div>;
}

function Drawer({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); }; window.addEventListener("keydown", onKeyDown); return () => window.removeEventListener("keydown", onKeyDown); }, [onClose]); return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><div className="drawer-heading"><div><div className="eyebrow">DETALHES</div><h2>{title}</h2></div><button type="button" onClick={onClose} aria-label="Fechar detalhes"><X size={19} /></button></div>{children}</aside></div>; }
function ContactDrawer({ contact, state, onClose }: { contact: Contact; state: AppState; onClose: () => void }) { const owner = state.users.find((user) => user.id === contact.ownerId); return <><div className="drawer-profile"><Avatar size="lg" user={{ name: contact.name, avatar: contact.name.split(" ").map((part) => part[0]).join("").slice(0, 2) }} /><div><h3>{contact.name}</h3><p>{contact.company}</p></div></div><div className="drawer-actions"><Button variant="soft" disabled title="Ação em breve"><Phone size={15} /> Ligar</Button><Button variant="soft" disabled title="Ação em breve"><Mail size={15} /> Email</Button></div><dl className="drawer-dl"><dt>Telefone</dt><dd>{contact.phone || "—"}</dd><dt>Email</dt><dd>{contact.email || "—"}</dd><dt>Responsável</dt><dd>{owner?.name ?? "—"}</dd><dt>Última conversa</dt><dd>há {timeAgo(contact.lastConversationAt)}</dd></dl><div className="drawer-block"><span className="context-label">TAGS</span><div className="tag-list">{contact.tags.map((tag) => <Badge key={tag}>{tag}</Badge>)}</div></div><div className="drawer-block"><span className="context-label">NOTAS</span><p className="drawer-note">{contact.notes || "Sem notas"}</p></div><Button variant="primary" className="wide" onClick={onClose}>Fechar detalhes</Button></>; }
function OpportunityDrawer({ opportunity, state }: { opportunity: Opportunity; state: AppState }) { const owner = state.users.find((user) => user.id === opportunity.ownerId); const contact = state.contacts.find((item) => item.id === opportunity.contactId); return <><div className="opportunity-drawer-hero"><Badge tone="teal">{stageLabels[opportunity.stage]}</Badge><h3>{opportunity.title}</h3><strong>{money(opportunity.value)}</strong><span>{opportunity.company}</span></div><dl className="drawer-dl"><dt>Contato</dt><dd>{contact?.name}</dd><dt>Responsável</dt><dd>{owner?.name}</dd><dt>Origem</dt><dd>{opportunity.source}</dd><dt>Última atividade</dt><dd>{opportunity.lastActivity}</dd></dl><div className="drawer-block"><span className="context-label">CONTEXTO</span><p className="drawer-note">{opportunity.note}</p></div></>; }

export default function App() {
  const [state, setState] = useState<AppState | null>(null); const [page, setPage] = useState<Page>("dashboard"); const [drawer, setDrawer] = useState<{ type: "contact" | "opportunity"; value: Contact | Opportunity } | null>(null); const [opportunityCreate, setOpportunityCreate] = useState<OpportunityCreate | null>(null); const [toast, setToast] = useState<Toast | null>(null); const [sidebarOpen, setSidebarOpen] = useState(false); const inviteToken = window.location.pathname.match(/^\/invite\/([^/]+)$/)?.[1];
  useEffect(() => { if (inviteToken) return; void loadState().then(setState).catch(() => setState(null)); }, [inviteToken]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(null), 3500); return () => window.clearTimeout(timer); }, [toast]);
  if (inviteToken) return <InviteAccept token={decodeURIComponent(inviteToken)} onLoggedIn={setState} />;
  if (!state) return <Login onLoggedIn={setState} />;
  const notify = (nextToast: Toast) => setToast(nextToast);
  const openOpportunityCreate = (contact: Contact, conversationId?: string) => setOpportunityCreate({ contactId: contact.id, conversationId });
  const createdOpportunity = (opportunity: Opportunity) => { setState({ ...state, opportunities: [...state.opportunities, opportunity] }); setOpportunityCreate(null); setDrawer({ type: "opportunity", value: opportunity }); notify({ tone: "success", message: "Oportunidade criada." }); };
  const content = page === "dashboard" ? <Dashboard state={state} setPage={setPage} /> : page === "inbox" ? <Inbox state={state} setState={setState} onOpenContact={(contact) => setDrawer({ type: "contact", value: contact })} onOpenOpportunity={(opportunity) => setDrawer({ type: "opportunity", value: opportunity })} onCreateOpportunity={openOpportunityCreate} notify={notify} /> : page === "crm" ? <Crm state={state} setState={setState} onOpenOpportunity={(opportunity) => setDrawer({ type: "opportunity", value: opportunity })} onCreateOpportunity={(contact) => openOpportunityCreate(contact)} notify={notify} /> : page === "contacts" ? <Contacts state={state} setState={setState} onOpenContact={(contact) => setDrawer({ type: "contact", value: contact })} /> : page === "team" ? <TeamPage state={state} setState={setState} notify={notify} /> : page === "channels" ? <ChannelsPage state={state} setState={setState} notify={notify} /> : <SettingsPage state={state} setState={setState} notify={notify} />;
  const logout = async () => { await api("/v1/auth/logout", { method: "POST" }).catch(() => undefined); setState(null); setPage("dashboard"); };
  return <div className={"app-shell " + (sidebarOpen ? "sidebar-open" : "")}><Sidebar page={page} setPage={(next) => { setPage(next); setSidebarOpen(false); }} user={state.user} organization={state.organization} onLogout={() => void logout()} /><div className="app-main"><Topbar page={page} onMenu={() => setSidebarOpen((value) => !value)} /><main className="app-content"><Onboarding state={state} setState={setState} />{content}</main></div>{drawer?.type === "contact" && <Drawer title={(drawer.value as Contact).name} onClose={() => setDrawer(null)}><ContactDrawer contact={drawer.value as Contact} state={state} onClose={() => setDrawer(null)} /></Drawer>}{drawer?.type === "opportunity" && <Drawer title="Oportunidade" onClose={() => setDrawer(null)}><OpportunityDrawer opportunity={drawer.value as Opportunity} state={state} /></Drawer>}{opportunityCreate && <OpportunityFormModal state={state} initialContactId={opportunityCreate.contactId} initialConversationId={opportunityCreate.conversationId} onClose={() => setOpportunityCreate(null)} onCreated={createdOpportunity} notify={notify} />}{toast && <div className={"toast " + toast.tone} role="status">{toast.message}</div>}</div>;
}
